import { useEffect, useMemo, useState } from 'react'
import { Link } from 'react-router-dom'
import { useAuth } from '../context/AuthContext'
import { getPerfil } from '../services/api'
import './PerfilPage.css'

const ROLES_CLIENTE = ['cliente_b2c', 'cliente_b2b']

const ETIQUETAS_ROL = {
  admin: 'Administrador',
  cliente_b2b: 'Cliente B2B',
  cliente_b2c: 'Paciente',
  ejecutivo: 'Ejecutivo',
  operador: 'Operador',
  analista: 'Analista',
  CLIENTE: 'Cliente',
  TRABAJADOR: 'Trabajador',
}

function camposIniciales(datos, rol) {
  // Soporta dos formatos:
  //   - Cliente (backend actual): { id, rut, telefono, email, first_name, last_name, institucion, direccion_principal, ... }
  //   - Cliente (legacy): { usuario: {...}, rut, telefono, tipo_cliente, institucion_nombre }
  //   - Trabajador: { id, username, email, first_name, last_name, rol, rut, telefono, ... }
  const esCliente = ROLES_CLIENTE.includes(rol) || rol === 'CLIENTE'
  const base = esCliente ? (datos?.usuario || datos || {}) : (datos || {})
  const dir = datos?.direccion_principal
  const direccionPrincipal = dir
    ? [dir.direccion, dir.num_direccion, dir.detalle_direccion, dir.comuna]
      .filter(Boolean)
      .join(' ')
    : ''
  return {
    first_name: base.first_name || '',
    last_name: base.last_name || '',
    email: base.email || '',
    rut: (esCliente ? datos?.rut : datos?.rut) || base.rut || '',
    telefono: (esCliente ? datos?.telefono : datos?.telefono) || base.telefono || '',
    direccion: base.direccion || datos?.direccion || direccionPrincipal || '',
  }
}

export default function PerfilPage() {
  const { usuario, actualizarPerfilUsuario } = useAuth()
  const [perfil, setPerfil] = useState(null)
  const [form, setForm] = useState({
    first_name: '', last_name: '', email: '', rut: '', telefono: '', direccion: '',
  })
  const [original, setOriginal] = useState(form)

  const [errores, setErrores] = useState({})
  const [errorGeneral, setErrorGeneral] = useState('')
  const [okMsg, setOkMsg] = useState('')
  const [cargando, setCargando] = useState(true)
  const [guardando, setGuardando] = useState(false)

  // El rol "real" para decidir si es editable. Aceptamos tanto el
  // formato del backend ('CLIENTE' / 'TRABAJADOR') como los roles internos
  // de Usuario (cliente_b2b, cliente_b2c, admin, ejecutivo, operador, analista).
  const rolPerfil = perfil?.rol || perfil?.Rol || usuario?.rol
  const datosPerfil = perfil?.datos || usuario?.datos
  const rolUsuarioInterno = useMemo(() => {
    if (ROLES_CLIENTE.includes(usuario?.rol)) return usuario.rol
    if (ROLES_CLIENTE.includes(datosPerfil?.usuario?.rol)) return datosPerfil.usuario.rol
    if (ROLES_CLIENTE.includes(datosPerfil?.rol)) return datosPerfil.rol
    return usuario?.rol || rolPerfil
  }, [usuario, datosPerfil, rolPerfil])

  const esCliente = ROLES_CLIENTE.includes(rolUsuarioInterno) || rolPerfil === 'CLIENTE'
  const editable = esCliente

  useEffect(() => {
    getPerfil()
      .then((res) => {
        const data = res?.data ?? res
        const perfilNormalizado = data?.datos ? data : (data?.data ?? data)
        setPerfil(perfilNormalizado)
        const iniciales = camposIniciales(
          perfilNormalizado?.datos,
          perfilNormalizado?.rol || perfilNormalizado?.Rol,
        )
        setForm(iniciales)
        setOriginal(iniciales)
      })
      .catch(() => setErrorGeneral('No se pudieron cargar los datos del perfil.'))
      .finally(() => setCargando(false))
  }, [])

  const setField = (campo, valor) => {
    setForm(f => ({ ...f, [campo]: valor }))
    if (errores[campo]) setErrores(e => ({ ...e, [campo]: '' }))
    if (okMsg) setOkMsg('')
  }

  const cambios = useMemo(() => {
    const diff = {}
    for (const k of Object.keys(form)) {
      if ((form[k] ?? '') !== (original[k] ?? '')) diff[k] = form[k]
    }
    return diff
  }, [form, original])

  const hayCambios = Object.keys(cambios).length > 0

  const validar = () => {
    const e = {}
    if (!form.first_name.trim()) e.first_name = 'El nombre es obligatorio.'
    if (!form.last_name.trim()) e.last_name = 'El apellido es obligatorio.'
    if (!form.email.trim()) e.email = 'El email es obligatorio.'
    else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.email)) e.email = 'Email inválido.'
    return e
  }

  const handleCancelar = () => {
    setForm(original)
    setErrores({})
    setErrorGeneral('')
    setOkMsg('')
  }

  const handleSubmit = async (ev) => {
    ev.preventDefault()
    setErrorGeneral('')
    setOkMsg('')
    const eVal = validar()
    if (Object.keys(eVal).length > 0) { setErrores(eVal); return }
    if (!hayCambios) {
      setErrorGeneral('No hay cambios para guardar.')
      return
    }
    setGuardando(true)
    try {
      const payload = {}
      for (const [k, v] of Object.entries(cambios)) {
        const valor = (v ?? '').toString().trim()
        if (valor) payload[k] = valor
      }
      const actualizado = await actualizarPerfilUsuario(payload)
      const nuevos = camposIniciales(actualizado?.datos, actualizado?.rol)
      setForm(nuevos)
      setOriginal(nuevos)
      setPerfil(prev => ({ ...prev, datos: actualizado?.datos, rol: actualizado?.rol }))
      setOkMsg('Datos actualizados correctamente.')
    } catch (err) {
      const data = err.response?.data
      if (data && typeof data === 'object') {
        const nuevosErrores = {}
        Object.entries(data).forEach(([campo, msg]) => {
          const m = Array.isArray(msg) ? msg.join(' ') : String(msg)
          if (campo === 'detail' || campo === 'non_field_errors') setErrorGeneral(m)
          else nuevosErrores[campo] = m
        })
        setErrores(nuevosErrores)
        if (Object.keys(nuevosErrores).length === 0 && !errorGeneral) {
          setErrorGeneral(JSON.stringify(data))
        }
      } else {
        setErrorGeneral('No se pudo actualizar el perfil. Intente nuevamente.')
      }
    } finally {
      setGuardando(false)
    }
  }

  if (cargando) return <div className="spinner" />

  const tipoCliente = datosPerfil?.tipo_cliente
  const institucion = datosPerfil?.institucion_nombre || datosPerfil?.nombre_institucion || datosPerfil?.institucion
  const username = datosPerfil?.usuario?.username || datosPerfil?.username

  // Detectar si el usuario tiene su perfil "incompleto" (datos básicos vacíos)
  const perfilIncompleto = editable && (
    !original.first_name || !original.last_name || !original.email
  )

  return (
    <div className="perfil-page">
      <div className="perfil-container">
        <header className="perfil-header">
          <h1>Mi perfil</h1>
          <p className="text-muted">
            Revisa y actualiza tus datos personales.
          </p>
        </header>

        <div className="perfil-layout">
          {/* ── Resumen lateral ── */}
          <aside className="perfil-resumen card">
            <div className="perfil-avatar">
              {(form.first_name || username || '?').trim().charAt(0).toUpperCase()}
            </div>
            <div className="perfil-resumen-nombre">
              {form.first_name || form.last_name
                ? `${form.first_name} ${form.last_name}`.trim()
                : username || 'Sin nombre'}
            </div>
            <span className="badge badge-info">
              {ETIQUETAS_ROL[rolUsuarioInterno] || ETIQUETAS_ROL[rolPerfil] || rolPerfil || 'Usuario'}
            </span>

            <dl className="perfil-meta">
              {username && (
                <>
                  <dt>Usuario</dt>
                  <dd>{username}</dd>
                </>
              )}
              {tipoCliente && (
                <>
                  <dt>Tipo de cuenta</dt>
                  <dd>{tipoCliente}</dd>
                </>
              )}
              {institucion && (
                <>
                  <dt>Institución</dt>
                  <dd>{institucion}</dd>
                </>
              )}
            </dl>

            <Link to="/panel" className="btn btn-secondary btn-block btn-sm">
              ← Volver al panel
            </Link>
          </aside>

          {/* ── Vista de datos personales (solo lectura) ── */}
          <section className="card perfil-vista">
            <h2 className="section-title">Mis datos</h2>
            <dl className="perfil-datos-grid">
              <div className="perfil-dato">
                <dt>Nombre</dt>
                <dd>{original.first_name || <span className="dato-vacio">— sin registrar —</span>}</dd>
              </div>
              <div className="perfil-dato">
                <dt>Apellido</dt>
                <dd>{original.last_name || <span className="dato-vacio">— sin registrar —</span>}</dd>
              </div>
              <div className="perfil-dato">
                <dt>Email</dt>
                <dd>{original.email || <span className="dato-vacio">— sin registrar —</span>}</dd>
              </div>
              <div className="perfil-dato">
                <dt>RUT</dt>
                <dd>{original.rut || <span className="dato-vacio">— sin registrar —</span>}</dd>
              </div>
              <div className="perfil-dato">
                <dt>Teléfono</dt>
                <dd>{original.telefono || <span className="dato-vacio">— sin registrar —</span>}</dd>
              </div>
              <div className="perfil-dato perfil-dato-full">
                <dt>Dirección</dt>
                <dd>{original.direccion || <span className="dato-vacio">— sin registrar —</span>}</dd>
              </div>
              {username && (
                <div className="perfil-dato">
                  <dt>Usuario</dt>
                  <dd>{username}</dd>
                </div>
              )}
              <div className="perfil-dato">
                <dt>Rol</dt>
                <dd>{ETIQUETAS_ROL[rolUsuarioInterno] || ETIQUETAS_ROL[rolPerfil] || rolPerfil || '—'}</dd>
              </div>
              {tipoCliente && (
                <div className="perfil-dato">
                  <dt>Tipo de cuenta</dt>
                  <dd>{tipoCliente}</dd>
                </div>
              )}
              {institucion && (
                <div className="perfil-dato perfil-dato-full">
                  <dt>Institución</dt>
                  <dd>{institucion}</dd>
                </div>
              )}
            </dl>
          </section>

          {/* ── Form de edición ── */}
          <section className="card perfil-form">
            <h2 className="section-title">Editar mis datos</h2>

            {!editable && (
              <div className="alert alert-info">
                Los datos de cuentas internas (trabajadores) deben ser actualizados
                por un administrador.
              </div>
            )}
            {editable && perfilIncompleto && !okMsg && (
              <div className="alert alert-info">
                Tu perfil está incompleto. Por favor completa tu <strong>nombre</strong>,
                <strong> apellido</strong> y <strong>email</strong> para mejorar tu experiencia.
              </div>
            )}
            {errorGeneral && <div className="alert alert-error">{errorGeneral}</div>}
            {okMsg && <div className="alert alert-success">{okMsg}</div>}

            <form onSubmit={handleSubmit} noValidate>
              <div className="grid-2">
                <div className="form-group">
                  <label>Nombre *</label>
                  <input
                    type="text"
                    value={form.first_name}
                    onChange={e => setField('first_name', e.target.value)}
                    disabled={!editable}
                    autoComplete="given-name"
                    placeholder="Ej: María"
                  />
                  {errores.first_name && <small className="campo-error">{errores.first_name}</small>}
                </div>
                <div className="form-group">
                  <label>Apellido *</label>
                  <input
                    type="text"
                    value={form.last_name}
                    onChange={e => setField('last_name', e.target.value)}
                    disabled={!editable}
                    autoComplete="family-name"
                    placeholder="Ej: González"
                  />
                  {errores.last_name && <small className="campo-error">{errores.last_name}</small>}
                </div>
              </div>

              <div className="form-group">
                <label>Email *</label>
                <input
                  type="email"
                  value={form.email}
                  onChange={e => setField('email', e.target.value)}
                  disabled={!editable}
                  autoComplete="email"
                  placeholder="tu@correo.cl"
                />
                {errores.email && <small className="campo-error">{errores.email}</small>}
              </div>

              <div className="grid-2">
                <div className="form-group">
                  <label>RUT</label>
                  <input
                    type="text"
                    value={form.rut}
                    onChange={e => setField('rut', e.target.value)}
                    disabled={!editable}
                    placeholder="12345678-9"
                  />
                  {errores.rut && <small className="campo-error">{errores.rut}</small>}
                </div>
                <div className="form-group">
                  <label>Teléfono</label>
                  <input
                    type="tel"
                    value={form.telefono}
                    onChange={e => setField('telefono', e.target.value)}
                    disabled={!editable}
                    placeholder="+56 9 XXXX XXXX"
                    autoComplete="tel"
                  />
                  {errores.telefono && <small className="campo-error">{errores.telefono}</small>}
                </div>
              </div>

              <div className="form-group">
                <label>Dirección</label>
                <textarea
                  rows={2}
                  value={form.direccion}
                  onChange={e => setField('direccion', e.target.value)}
                  disabled={!editable}
                  placeholder="Calle, número, depto, comuna"
                  autoComplete="street-address"
                />
                {errores.direccion && <small className="campo-error">{errores.direccion}</small>}
              </div>

              {editable && (
                <div className="perfil-actions">
                  <button
                    type="button"
                    className="btn btn-secondary"
                    onClick={handleCancelar}
                    disabled={guardando || !hayCambios}
                  >
                    Descartar cambios
                  </button>
                  <button
                    type="submit"
                    className="btn btn-primary"
                    disabled={guardando || !hayCambios}
                  >
                    {guardando ? 'Guardando...' : 'Guardar cambios'}
                  </button>
                </div>
              )}
            </form>
          </section>
        </div>
      </div>
    </div>
  )
}

import { useEffect, useMemo, useState } from 'react'
import { Link } from 'react-router-dom'
import { useCombobox } from 'downshift'
import { useAuth } from '../context/AuthContext'
import { getPerfil, obtenerComunasDespacho, obtenerRegionesDespacho } from '../services/api'
import './PerfilPage.css'

const ROLES_CLIENTE = ['cliente_b2c', 'cliente_b2b']

const ETIQUETAS_ROL = {
  admin: 'Administrador',
  cliente_b2b: 'Cliente B2B',
  cliente_b2c: 'Paciente',
  ejecutivo: 'Ejecutivo',
  operador: 'Operador',
  analista: 'Analista',
  CLIENTE: 'Cliente',
  TRABAJADOR: 'Trabajador',
}

function camposIniciales(datos, rol) {
  // Soporta dos formatos:
  //   - Cliente (backend actual): { id, rut, telefono, email, first_name, last_name, institucion, direccion_principal, ... }
  //   - Cliente (legacy): { usuario: {...}, rut, telefono, tipo_cliente, institucion_nombre }
  //   - Trabajador: { id, username, email, first_name, last_name, rol, rut, telefono, ... }
  const esCliente = ROLES_CLIENTE.includes(rol) || rol === 'CLIENTE'
  const base = esCliente ? (datos?.usuario || datos || {}) : (datos || {})
  const dir = datos?.direccion_principal
  const direccionPrincipal = dir
    ? [dir.direccion, dir.num_direccion, dir.detalle_direccion, dir.comuna]
      .filter(Boolean)
      .join(' ')
    : ''
  return {
    first_name: base.first_name || '',
    last_name: base.last_name || '',
    email: base.email || '',
    rut: (esCliente ? datos?.rut : datos?.rut) || base.rut || '',
    telefono: (esCliente ? datos?.telefono : datos?.telefono) || base.telefono || '',
    direccion: base.direccion || datos?.direccion || direccionPrincipal || '',
    regionId: dir?.region?.id || dir?.region_id || '',
    comunaId: dir?.comuna_detalle?.id || dir?.comuna || dir?.comuna_id || '',
  }
}

function UbicacionCombobox({
  label,
  placeholder,
  items,
  selectedId,
  onSelect,
  disabled = false,
  loading = false,
  emptyText = 'Sin resultados',
}) {
  const selectedItem = items.find(item => String(item.id) === String(selectedId)) || null
  const [inputItems, setInputItems] = useState(items)

  useEffect(() => {
    setInputItems(items)
  }, [items])

  const normalizarTexto = (valor) => String(valor || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()

  const {
    isOpen,
    getLabelProps,
    getMenuProps,
    getInputProps,
    getItemProps,
    getToggleButtonProps,
    highlightedIndex,
    selectedItem: downshiftSelectedItem,
  } = useCombobox({
    items: inputItems,
    selectedItem,
    itemToString: item => (item ? item.nombre : ''),
    onInputValueChange: ({ inputValue }) => {
      const texto = normalizarTexto(inputValue || '')
      const filtrados = items.filter(item =>
        normalizarTexto(item.nombre).includes(texto)
      )
      setInputItems(filtrados)
    },
    onSelectedItemChange: ({ selectedItem: nuevoItem }) => {
      onSelect(nuevoItem || null)
    },
  })

  return (
    <div className="ubicacion-combobox">
      <label {...getLabelProps()}>{label}</label>

      <div className="ubicacion-combobox__control">
        <input
          {...getInputProps({
            placeholder,
            disabled: disabled || loading,
          })}
        />

        <button
          type="button"
          className="ubicacion-combobox__toggle"
          disabled={disabled || loading}
          {...getToggleButtonProps()}
          aria-label="Abrir opciones"
        >
          ▾
        </button>
      </div>

      <ul
        {...getMenuProps()}
        className={`ubicacion-combobox__menu ${isOpen ? 'ubicacion-combobox__menu--open' : ''}`}
      >
        {isOpen && (
          <>
            {loading && (
              <li className="ubicacion-combobox__option ubicacion-combobox__option--empty">
                Cargando...
              </li>
            )}

            {!loading && inputItems.length === 0 && (
              <li className="ubicacion-combobox__option ubicacion-combobox__option--empty">
                {emptyText}
              </li>
            )}

            {!loading && inputItems.map((item, index) => (
              <li
                key={item.id}
                className={`ubicacion-combobox__option ${
                  highlightedIndex === index ? 'ubicacion-combobox__option--highlighted' : ''
                } ${
                  downshiftSelectedItem?.id === item.id ? 'ubicacion-combobox__option--selected' : ''
                }`}
                {...getItemProps({ item, index })}
              >
                {item.nombre}
              </li>
            ))}
          </>
        )}
      </ul>
    </div>
  )
}

function obtenerListaRespuesta(data) {
  return data?.results || data || []
}

function normalizarUbicacion(item) {
  if (item === null || item === undefined) return null
  if (typeof item === 'string' || typeof item === 'number') {
    return { id: String(item), nombre: String(item) }
  }
  return {
    id: item.id ?? item.codigo ?? item.value ?? item.pk ?? item.region_id ?? item.comuna_id ?? item.nombre ?? item.name,
    nombre: item.nombre || item.name || item.descripcion || item.label || item.region || item.comuna || String(item.id),
  }
}

function normalizarId(valor) {
  const texto = String(valor ?? '').trim()
  if (!texto) return null
  return /^\d+$/.test(texto) ? Number(texto) : texto
}

export default function PerfilPage() {
  const { usuario, actualizarPerfilUsuario } = useAuth()
  const [perfil, setPerfil] = useState(null)
  const [form, setForm] = useState({
    first_name: '',
    last_name: '',
    email: '',
    rut: '',
    telefono: '',
    direccion: '',
    regionId: '',
    comunaId: '',
  })
  const [original, setOriginal] = useState(form)

  const [errores, setErrores] = useState({})
  const [errorGeneral, setErrorGeneral] = useState('')
  const [okMsg, setOkMsg] = useState('')
  const [cargando, setCargando] = useState(true)
  const [guardando, setGuardando] = useState(false)
  const [editando, setEditando] = useState(false)
  const [regiones, setRegiones] = useState([])
  const [comunas, setComunas] = useState([])
  const [cargandoRegiones, setCargandoRegiones] = useState(false)
  const [cargandoComunas, setCargandoComunas] = useState(false)

  // El rol "real" para decidir si es editable. Aceptamos tanto el
  // formato del backend ('CLIENTE' / 'TRABAJADOR') como los roles internos
  // de Usuario (cliente_b2b, cliente_b2c, admin, ejecutivo, operador, analista).
  const rolPerfil = perfil?.rol || perfil?.Rol || usuario?.rol
  const datosPerfil = perfil?.datos || usuario?.datos
  const rolUsuarioInterno = useMemo(() => {
    if (ROLES_CLIENTE.includes(usuario?.rol)) return usuario.rol
    if (ROLES_CLIENTE.includes(datosPerfil?.usuario?.rol)) return datosPerfil.usuario.rol
    if (ROLES_CLIENTE.includes(datosPerfil?.rol)) return datosPerfil.rol
    return usuario?.rol || rolPerfil
  }, [usuario, datosPerfil, rolPerfil])

  const editable = true

  useEffect(() => {
    let activo = true
    const cargarRegiones = async () => {
      setCargandoRegiones(true)
      try {
        const { data } = await obtenerRegionesDespacho()
        const lista = obtenerListaRespuesta(data)
          .map(normalizarUbicacion)
          .filter(Boolean)
        if (activo) setRegiones(lista)
      } catch {
        if (activo) setRegiones([])
      } finally {
        if (activo) setCargandoRegiones(false)
      }
    }
    cargarRegiones()
    return () => { activo = false }
  }, [])

  useEffect(() => {
    if (!form.regionId) {
      setComunas([])
      return
    }
    let activo = true
    const cargarComunas = async () => {
      setCargandoComunas(true)
      try {
        const { data } = await obtenerComunasDespacho(form.regionId)
        const lista = obtenerListaRespuesta(data)
          .map(normalizarUbicacion)
          .filter(Boolean)
        if (activo) setComunas(lista)
      } catch {
        if (activo) setComunas([])
      } finally {
        if (activo) setCargandoComunas(false)
      }
    }
    cargarComunas()
    return () => { activo = false }
  }, [form.regionId])

  useEffect(() => {
    getPerfil()
      .then((res) => {
        const data = res?.data ?? res
        const perfilNormalizado = data?.datos ? data : (data?.data ?? data)
        setPerfil(perfilNormalizado)
        const iniciales = camposIniciales(
          perfilNormalizado?.datos,
          perfilNormalizado?.rol || perfilNormalizado?.Rol,
        )
        setForm(iniciales)
        setOriginal(iniciales)
      })
      .catch(() => setErrorGeneral('No se pudieron cargar los datos del perfil.'))
      .finally(() => setCargando(false))
  }, [])

  const setField = (campo, valor) => {
    setForm(f => ({ ...f, [campo]: valor }))
    if (errores[campo]) setErrores(e => ({ ...e, [campo]: '' }))
    if (okMsg) setOkMsg('')
  }

  const cambios = useMemo(() => {
    const diff = {}
    for (const k of Object.keys(form)) {
      if ((form[k] ?? '') !== (original[k] ?? '')) diff[k] = form[k]
    }
    return diff
  }, [form, original])

  const hayCambios = Object.keys(cambios).length > 0

  const validar = () => {
    const e = {}
    if (!form.first_name.trim()) e.first_name = 'El nombre es obligatorio.'
    if (!form.last_name.trim()) e.last_name = 'El apellido es obligatorio.'
    if (!form.email.trim()) e.email = 'El email es obligatorio.'
    else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.email)) e.email = 'Email inválido.'
    return e
  }

  const handleCancelar = () => {
    setForm(original)
    setErrores({})
    setErrorGeneral('')
    setOkMsg('')
    setEditando(false)
  }

  const handleSubmit = async (ev) => {
    ev.preventDefault()
    setErrorGeneral('')
    setOkMsg('')
    const eVal = validar()
    if (Object.keys(eVal).length > 0) { setErrores(eVal); return }
    if (!hayCambios) {
      setErrorGeneral('No hay cambios para guardar.')
      return
    }
    setGuardando(true)
    try {
      const payload = {}
      let direccionCambiada = false
      for (const [k, v] of Object.entries(cambios)) {
        if (k === 'regionId' || k === 'comunaId') {
          direccionCambiada = true
          continue
        }
        if (k === 'direccion') direccionCambiada = true
        const valor = (v ?? '').toString().trim()
        if (valor) payload[k] = valor
      }
      if (direccionCambiada) {
        payload.direccion_principal = {
          direccion: form.direccion?.trim() || '',
          comuna: normalizarId(form.comunaId),
          es_principal: true,
        }
      }
      const actualizado = await actualizarPerfilUsuario(payload)
      const nuevos = camposIniciales(actualizado?.datos, actualizado?.rol)
      setForm(nuevos)
      setOriginal(nuevos)
      setPerfil(prev => ({ ...prev, datos: actualizado?.datos, rol: actualizado?.rol }))
      setOkMsg('Datos actualizados correctamente.')
      setEditando(false)
    } catch (err) {
      const data = err.response?.data
      if (data && typeof data === 'object') {
        const nuevosErrores = {}
        Object.entries(data).forEach(([campo, msg]) => {
          const m = Array.isArray(msg) ? msg.join(' ') : String(msg)
          if (campo === 'detail' || campo === 'non_field_errors') setErrorGeneral(m)
          else nuevosErrores[campo] = m
        })
        setErrores(nuevosErrores)
        if (Object.keys(nuevosErrores).length === 0 && !errorGeneral) {
          setErrorGeneral(JSON.stringify(data))
        }
      } else {
        setErrorGeneral('No se pudo actualizar el perfil. Intente nuevamente.')
      }
    } finally {
      setGuardando(false)
    }
  }

  if (cargando) return <div className="spinner" />

  const tipoCliente = datosPerfil?.tipo_cliente
  const institucion = datosPerfil?.institucion_nombre || datosPerfil?.nombre_institucion || datosPerfil?.institucion
  const username = datosPerfil?.usuario?.username || datosPerfil?.username
  const direccionPrincipal = datosPerfil?.direccion_principal
  const regionNombre = regiones.find(r => String(r.id) === String(form.regionId))?.nombre
    || direccionPrincipal?.region?.nombre
    || direccionPrincipal?.region_nombre
  const comunaNombre = comunas.find(c => String(c.id) === String(form.comunaId))?.nombre
    || direccionPrincipal?.comuna_detalle?.nombre
    || direccionPrincipal?.comuna_nombre

  // Detectar si el usuario tiene su perfil "incompleto" (datos básicos vacíos)
  const perfilIncompleto = editable && (
    !original.first_name || !original.last_name || !original.email
  )

  return (
    <div className="perfil-page">
      <div className="perfil-container">
        <header className="perfil-header">
          <h1>Mi perfil</h1>
          <p className="text-muted">
            Revisa y actualiza tus datos personales.
          </p>
        </header>

        <div className="perfil-layout">
          {/* ── Resumen lateral ── */}
          <aside className="perfil-resumen card">
            <div className="perfil-avatar">
              {(form.first_name || username || '?').trim().charAt(0).toUpperCase()}
            </div>
            <div className="perfil-resumen-nombre">
              {form.first_name || form.last_name
                ? `${form.first_name} ${form.last_name}`.trim()
                : username || 'Sin nombre'}
            </div>
            <span className="badge badge-info">
              {ETIQUETAS_ROL[rolUsuarioInterno] || ETIQUETAS_ROL[rolPerfil] || rolPerfil || 'Usuario'}
            </span>

            <dl className="perfil-meta">
              {username && (
                <>
                  <dt>Usuario</dt>
                  <dd>{username}</dd>
                </>
              )}
              {tipoCliente && (
                <>
                  <dt>Tipo de cuenta</dt>
                  <dd>{tipoCliente}</dd>
                </>
              )}
              {institucion && (
                <>
                  <dt>Institución</dt>
                  <dd>{institucion}</dd>
                </>
              )}
            </dl>

            <Link to="/panel" className="btn btn-secondary btn-block btn-sm">
              ← Volver al panel
            </Link>
          </aside>

          {/* ── Vista de datos personales (solo lectura) ── */}
          <section className="card perfil-vista">
            <div className="perfil-vista-header">
              <h2 className="section-title">Mis datos</h2>
              {editable && !editando && (
                <button
                  type="button"
                  className="btn btn-secondary btn-sm"
                  onClick={() => setEditando(true)}
                >
                  Editar datos
                </button>
              )}
            </div>
            <dl className="perfil-datos-grid">
              <div className="perfil-dato">
                <dt>Nombre</dt>
                <dd>{original.first_name || <span className="dato-vacio">— sin registrar —</span>}</dd>
              </div>
              <div className="perfil-dato">
                <dt>Apellido</dt>
                <dd>{original.last_name || <span className="dato-vacio">— sin registrar —</span>}</dd>
              </div>
              <div className="perfil-dato">
                <dt>Email</dt>
                <dd>{original.email || <span className="dato-vacio">— sin registrar —</span>}</dd>
              </div>
              <div className="perfil-dato">
                <dt>RUT</dt>
                <dd>{original.rut || <span className="dato-vacio">— sin registrar —</span>}</dd>
              </div>
              <div className="perfil-dato">
                <dt>Teléfono</dt>
                <dd>{original.telefono || <span className="dato-vacio">— sin registrar —</span>}</dd>
              </div>
              <div className="perfil-dato perfil-dato-full">
                <dt>Dirección</dt>
                <dd>{original.direccion || <span className="dato-vacio">— sin registrar —</span>}</dd>
              </div>
              <div className="perfil-dato">
                <dt>Región</dt>
                <dd>{regionNombre || form.regionId || <span className="dato-vacio">— sin registrar —</span>}</dd>
              </div>
              <div className="perfil-dato">
                <dt>Comuna</dt>
                <dd>{comunaNombre || form.comunaId || <span className="dato-vacio">— sin registrar —</span>}</dd>
              </div>
              {username && (
                <div className="perfil-dato">
                  <dt>Usuario</dt>
                  <dd>{username}</dd>
                </div>
              )}
              <div className="perfil-dato">
                <dt>Rol</dt>
                <dd>{ETIQUETAS_ROL[rolUsuarioInterno] || ETIQUETAS_ROL[rolPerfil] || rolPerfil || '—'}</dd>
              </div>
              {tipoCliente && (
                <div className="perfil-dato">
                  <dt>Tipo de cuenta</dt>
                  <dd>{tipoCliente}</dd>
                </div>
              )}
              {institucion && (
                <div className="perfil-dato perfil-dato-full">
                  <dt>Institución</dt>
                  <dd>{institucion}</dd>
                </div>
              )}
            </dl>
            {editable && editando && (
              <div className="perfil-vista-actions">
                <button
                  type="button"
                  className="btn btn-secondary"
                  onClick={handleCancelar}
                  disabled={guardando || !hayCambios}
                >
                  Cancelar cambios
                </button>
                <button
                  type="submit"
                  className="btn btn-primary"
                  form="perfil-form"
                  disabled={guardando || !hayCambios}
                >
                  {guardando ? 'Guardando...' : 'Guardar cambios'}
                </button>
              </div>
            )}
          </section>

          {/* ── Form de edición ── */}
          <section className="card perfil-form">
            <h2 className="section-title">Editar mis datos</h2>

            {editable && perfilIncompleto && !okMsg && (
              <div className="alert alert-info">
                Tu perfil está incompleto. Por favor completa tu <strong>nombre</strong>,
                <strong> apellido</strong> y <strong>email</strong> para mejorar tu experiencia.
              </div>
            )}
            {errorGeneral && <div className="alert alert-error">{errorGeneral}</div>}
            {okMsg && <div className="alert alert-success">{okMsg}</div>}

            <form id="perfil-form" onSubmit={handleSubmit} noValidate>
              <div className="grid-2">
                <div className="form-group">
                  <label>Nombre *</label>
                  <input
                    type="text"
                    value={form.first_name}
                    onChange={e => setField('first_name', e.target.value)}
                    disabled={!editable || !editando}
                    autoComplete="given-name"
                    placeholder="Ej: María"
                  />
                  {errores.first_name && <small className="campo-error">{errores.first_name}</small>}
                </div>
                <div className="form-group">
                  <label>Apellido *</label>
                  <input
                    type="text"
                    value={form.last_name}
                    onChange={e => setField('last_name', e.target.value)}
                    disabled={!editable || !editando}
                    autoComplete="family-name"
                    placeholder="Ej: González"
                  />
                  {errores.last_name && <small className="campo-error">{errores.last_name}</small>}
                </div>
              </div>

              <div className="form-group">
                <label>Email *</label>
                <input
                  type="email"
                  value={form.email}
                  onChange={e => setField('email', e.target.value)}
                  disabled={!editable || !editando}
                  autoComplete="email"
                  placeholder="tu@correo.cl"
                />
                {errores.email && <small className="campo-error">{errores.email}</small>}
              </div>

              <div className="grid-2">
                <div className="form-group">
                  <label>RUT</label>
                  <input
                    type="text"
                    value={form.rut}
                    onChange={e => setField('rut', e.target.value)}
                    disabled={!editable || !editando}
                    placeholder="12345678-9"
                  />
                  {errores.rut && <small className="campo-error">{errores.rut}</small>}
                </div>
                <div className="form-group">
                  <label>Teléfono</label>
                  <input
                    type="tel"
                    value={form.telefono}
                    onChange={e => setField('telefono', e.target.value)}
                    disabled={!editable || !editando}
                    placeholder="+56 9 XXXX XXXX"
                    autoComplete="tel"
                  />
                  {errores.telefono && <small className="campo-error">{errores.telefono}</small>}
                </div>
              </div>

              <div className="form-group">
                <label>Dirección</label>
                <textarea
                  rows={2}
                  value={form.direccion}
                  onChange={e => setField('direccion', e.target.value)}
                  disabled={!editable || !editando}
                  placeholder="Calle, número, depto, comuna"
                  autoComplete="street-address"
                />
                {errores.direccion && <small className="campo-error">{errores.direccion}</small>}
              </div>

              <div className="grid-2">
                <div className="form-group">
                  <UbicacionCombobox
                    label="Región"
                    placeholder="Busca o selecciona una región"
                    items={regiones}
                    selectedId={form.regionId}
                    loading={cargandoRegiones}
                    disabled={!editable || !editando || cargandoRegiones || regiones.length === 0}
                    emptyText="No se encontraron regiones"
                    onSelect={(region) => {
                      setField('regionId', region?.id || '')
                      setField('comunaId', '')
                    }}
                  />
                  {errores.regionId && <small className="campo-error">{errores.regionId}</small>}
                </div>
                <div className="form-group">
                  <UbicacionCombobox
                    label="Comuna"
                    placeholder={form.regionId ? 'Busca o selecciona una comuna' : 'Selecciona una región primero'}
                    items={comunas}
                    selectedId={form.comunaId}
                    loading={cargandoComunas}
                    disabled={!editable || !editando || !form.regionId || cargandoComunas}
                    emptyText="No se encontraron comunas"
                    onSelect={(comuna) => {
                      setField('comunaId', comuna?.id || '')
                    }}
                  />
                  {errores.comunaId && <small className="campo-error">{errores.comunaId}</small>}
                </div>
              </div>
            </form>
          </section>
        </div>
      </div>
    </div>
  )
}

.registro-page {
  min-height: calc(100vh - 160px);
  padding: 34px 20px;
  background: linear-gradient(135deg, #e0f2fe 0%, #f8fafc 48%, #ecfdf5 100%);
  display: flex;
  justify-content: center;
}

.registro-card {
  width: 100%;
  max-width: 920px;
  background: #fff;
  border: 1px solid var(--color-border);
  border-radius: 8px;
  box-shadow: var(--shadow-md);
  padding: 32px;
}

.registro-header {
  text-align: center;
  margin-bottom: 24px;
}

.registro-kicker {
  display: inline-block;
  color: #0f766e;
  font-size: 0.78rem;
  font-weight: 800;
  text-transform: uppercase;
  margin-bottom: 6px;
}

.registro-header h1 {
  color: var(--color-primary);
  font-size: 1.8rem;
  margin-bottom: 6px;
}

.registro-header p {
  color: var(--color-text-muted);
}

.registro-tipo {
  border: 0;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
  margin-bottom: 22px;
}

.registro-tipo legend {
  grid-column: 1 / -1;
  font-weight: 700;
  margin-bottom: 4px;
}

.tipo-card {
  text-align: left;
  background: #f8fafc;
  border: 1px solid var(--color-border);
  border-radius: 8px;
  padding: 16px;
  color: var(--color-text);
}

.tipo-card strong,
.tipo-card span {
  display: block;
}

.tipo-card strong {
  margin-bottom: 4px;
}

.tipo-card span {
  color: var(--color-text-muted);
  font-size: 0.84rem;
}

.tipo-card-activo {
  border-color: var(--color-primary);
  background: #e0f2fe;
  box-shadow: 0 0 0 3px rgba(0,119,182,0.1);
}

.registro-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

.registro-full {
  grid-column: 1 / -1;
}

.registro-card small {
  color: var(--color-text-muted);
  display: block;
  margin-top: 5px;
  font-size: 0.78rem;
}

.registro-error {
  color: var(--color-danger);
  display: block;
  font-size: 0.78rem;
  margin-top: 5px;
}

.password-field {
  position: relative;
  display: flex;
  align-items: center;
}

.password-field input {
  padding-right: 70px;
}

.password-toggle {
  position: absolute;
  right: 8px;
  top: 50%;
  transform: translateY(-50%);
  background: transparent;
  border: 0;
  color: var(--color-primary);
  font-weight: 600;
  font-size: 0.85rem;
  cursor: pointer;
  padding: 4px;
  line-height: 0;
}

.password-toggle-icon {
  width: 18px;
  height: 18px;
  display: block;
}

.password-toggle:focus {
  outline: 2px solid rgba(0,119,182,0.3);
  outline-offset: 2px;
}

.registro-login-link {
  text-align: center;
  color: var(--color-text-muted);
  font-size: 0.9rem;
  margin-top: 18px;
}

@media (max-width: 720px) {
  .registro-card {
    padding: 24px;
  }

  .registro-tipo,
  .registro-grid {
    grid-template-columns: 1fr;
  }

  .registro-full {
    grid-column: auto;
  }
}

