import { useState, useEffect } from 'react'
import { Link } from 'react-router-dom'
import { registrarUsuario, obtenerRegiones, obtenerComunas } from '../services/api'
import './RegistroPage.css'

const TIPO_CLIENTE = {
  particular: 'PARTICULAR',
  institucional: 'INSTITUCIONAL',
}

const FORM_INICIAL = {
  tipoCliente: TIPO_CLIENTE.particular,
  nombre: '',
  apellido: '',
  email: '',
  telefono: '',
  rut: '',
  pasaporte: '',
  institucionId: '',
  institucionNombre: '',
  regionId: null,
  regionNombre: '',
  comunaId: null,
  comunaNombre: '',
  direccion: '',
  numDireccion: '',
  detalleDireccion: '',
  referencia: '',
  nombreReceptor: '',
  telefonoReceptor: '',
  password: '',
  confirmPassword: '',
}

function normalizarBusqueda(valor) {
  return String(valor || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
}

function escapeRegExp(valor) {
  return String(valor || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
}

function filtrarOpciones(opciones, busqueda) {
  const query = normalizarBusqueda(busqueda)
  if (!query) return opciones
  const regex = new RegExp(escapeRegExp(query))
  return opciones.filter((opcion) => regex.test(normalizarBusqueda(opcion.nombre)))
}

function validarEmail(email) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)
}

function validarTextoGeneral(valor) {
  const texto = String(valor || '').trim()
  if (texto.length < 2) return false
  return !/^\d+$/.test(texto)
}

function validarTelefonoChileno(valor) {
  const telefono = String(valor || '').trim()
  if (!/^\+?\d+$/.test(telefono)) return false

  if (telefono.startsWith('+56')) {
    const numero = telefono.slice(3)
    return /^\d{8,9}$/.test(numero)
  }

  return /^\d{8,9}$/.test(telefono)
}

function limpiarRut(rut) {
  return String(rut || '').replace(/\./g, '').replace(/-/g, '').trim().toUpperCase()
}

function calcularDigitoRut(cuerpo) {
  let suma = 0
  let multiplo = 2

  for (let i = cuerpo.length - 1; i >= 0; i -= 1) {
    suma += Number(cuerpo[i]) * multiplo
    multiplo = multiplo === 7 ? 2 : multiplo + 1
  }

  const resto = 11 - (suma % 11)
  if (resto === 11) return '0'
  if (resto === 10) return 'K'
  return String(resto)
}

function validarRutChileno(rut) {
  const limpio = limpiarRut(rut)
  if (!/^\d{6,8}[0-9K]$/.test(limpio)) return false

  const cuerpo = limpio.slice(0, -1)
  const dv = limpio.slice(-1)
  return calcularDigitoRut(cuerpo) === dv
}

export default function RegistroPage() {
  const [form, setForm] = useState(FORM_INICIAL)
  const [errores, setErrores] = useState({})
  const [enviado, setEnviado] = useState(false)
  const [enviando, setEnviando] = useState(false)
  const [mostrarPassword, setMostrarPassword] = useState(false)
  const [mostrarConfirmacion, setMostrarConfirmacion] = useState(false)
  const [regiones, setRegiones] = useState([])
  const [comunas, setComunas] = useState([])
  const [cargandoRegiones, setCargandoRegiones] = useState(false)
  const [cargandoComunas, setCargandoComunas] = useState(false)
  const [regionSearch, setRegionSearch] = useState('')
  const [comunaSearch, setComunaSearch] = useState('')
  const [regionAbierto, setRegionAbierto] = useState(false)
  const [comunaAbierto, setComunaAbierto] = useState(false)

  const esInstitucional = form.tipoCliente === TIPO_CLIENTE.institucional

  useEffect(() => {
    const cargarRegiones = async () => {
      try {
        setCargandoRegiones(true)
        const { data } = await obtenerRegiones()
        setRegiones(data || [])
      } finally {
        setCargandoRegiones(false)
      }
    }

    cargarRegiones()
  }, [])

  useEffect(() => {
    if (!form.regionId) {
      setComunas([])
      setComunaSearch('')
      return
    }

    const cargarComunas = async () => {
      try {
        setCargandoComunas(true)
        const { data } = await obtenerComunas({ region_id: form.regionId })
        setComunas(data || [])
      } finally {
        setCargandoComunas(false)
      }
    }

    cargarComunas()
  }, [form.regionId])

  const actualizarCampo = (campo, valor) => {
    setForm(prev => ({ ...prev, [campo]: valor }))
    setErrores(prev => {
      if (campo === 'tipoCliente') return {}
      return { ...prev, [campo]: '' }
    })
    setEnviado(false)
  }

  const seleccionarRegion = (region) => {
    actualizarCampo('regionId', region.id)
    actualizarCampo('regionNombre', region.nombre)
    actualizarCampo('comunaId', null)
    actualizarCampo('comunaNombre', '')
    setRegionSearch(region.nombre)
    setComunaSearch('')
    setRegionAbierto(false)
  }

  const seleccionarComuna = (comuna) => {
    actualizarCampo('comunaId', comuna.id)
    actualizarCampo('comunaNombre', comuna.nombre)
    setComunaSearch(comuna.nombre)
    setComunaAbierto(false)
  }

  const handleSubmit = async (event) => {
    event.preventDefault()
    setEnviado(false)

    if (!validarFormulario()) return

    const usuario = {
      username: form.email,
      email: form.email,
      first_name: form.nombre,
      last_name: form.apellido,
      password: form.password,
      password2: form.confirmPassword,
    }

    const direccionEntrega = {
      direccion: form.direccion,
      num_direccion: form.numDireccion,
      detalle_direccion: form.detalleDireccion || null,
      comuna: form.comunaId,
      referencia: form.referencia || null,
      nombre_receptor: form.nombreReceptor || null,
      telefono_receptor: form.telefonoReceptor || null,
      es_principal: true,
    }

    const payload = {
      usuario,
      rut: form.rut || null,
      pasaporte: form.pasaporte || null,
      tipo_cliente: form.tipoCliente,
      telefono: form.telefono,
      institucion_id: null,
      datos_institucion: null,
      direccion_entrega: direccionEntrega,
    }

    if (esInstitucional) {
      if (form.institucionId) {
        payload.institucion_id = Number(form.institucionId)
      } else {
        payload.datos_institucion = { nombre: form.institucionNombre }
      }
    }

    try {
      setEnviando(true)
      await registrarUsuario(payload)
      setEnviado(true)
      setForm(FORM_INICIAL)
      setRegionSearch('')
      setComunaSearch('')
    } catch (error) {
      const data = error.response?.data
      setErrores(
        data && typeof data === 'object'
          ? data
          : { general: 'No se pudo crear la cuenta. Intenta nuevamente.' }
      )
    } finally {
      setEnviando(false)
    }
  }

  const renderError = (campo) =>
    errores[campo] ? <span className="registro-error">{errores[campo]}</span> : null

  return (
    <main className="registro-page">
      <section className="registro-card">
        <div className="registro-header">
          <span className="registro-kicker">Nueva cuenta</span>
          <h1>Crear cuenta MEDISTOCK</h1>
          <p>Regístrate como paciente o cliente institucional.</p>
        </div>

        {enviado && (
          <div className="alert alert-success">
            Cuenta creada correctamente. Ya puedes iniciar sesión.
          </div>
        )}

        {errores.general && (
          <div className="alert alert-danger">
            {errores.general}
          </div>
        )}

        <form onSubmit={handleSubmit} noValidate>
          <fieldset className="registro-tipo">
            <legend>Tipo de cliente</legend>
            <button
              type="button"
              className={`tipo-card ${!esInstitucional ? 'tipo-card-activo' : ''}`}
              onClick={() => actualizarCampo('tipoCliente', TIPO_CLIENTE.particular)}
            >
              <strong>Particular</strong>
              <span>Compra para uso personal.</span>
            </button>
            <button
              type="button"
              className={`tipo-card ${esInstitucional ? 'tipo-card-activo' : ''}`}
              onClick={() => actualizarCampo('tipoCliente', TIPO_CLIENTE.institucional)}
            >
              <strong>Institucional</strong>
              <span>Cuenta para instituciones o empresas.</span>
            </button>
          </fieldset>

          <div className="registro-grid">
            <div className="form-group">
              <label>Nombre *</label>
              <input
                value={form.nombre}
                onChange={e => actualizarCampo('nombre', e.target.value)}
                placeholder="Ej: Carla"
              />
              {renderError('nombre')}
            </div>
            <div className="form-group">
              <label>Apellido *</label>
              <input
                value={form.apellido}
                onChange={e => actualizarCampo('apellido', e.target.value)}
                placeholder="Ej: González"
              />
              {renderError('apellido')}
            </div>
            <div className="form-group">
              <label>Correo electrónico *</label>
              <input
                type="email"
                value={form.email}
                onChange={e => actualizarCampo('email', e.target.value)}
                placeholder="correo@dominio.com"
              />
              {renderError('email')}
            </div>
            <div className="form-group">
              <label>Teléfono *</label>
              <input
                value={form.telefono}
                onChange={e => actualizarCampo('telefono', e.target.value)}
                placeholder="+56912345678"
              />
              {renderError('telefono')}
            </div>
            <div className="form-group">
              <label>RUT</label>
              <input
                value={form.rut}
                onChange={e => actualizarCampo('rut', e.target.value)}
                placeholder="12.345.678-5"
              />
              {renderError('rut')}
            </div>
            <div className="form-group">
              <label>Pasaporte</label>
              <input
                value={form.pasaporte}
                onChange={e => actualizarCampo('pasaporte', e.target.value)}
                placeholder="Ej: AB123456"
              />
              {renderError('pasaporte')}
            </div>
          </div>

          {esInstitucional && (
            <div className="registro-grid">
              <div className="form-group">
                <label>ID institución</label>
                <input
                  value={form.institucionId}
                  onChange={e => actualizarCampo('institucionId', e.target.value)}
                  placeholder="Ej: 12"
                />
                {renderError('institucionId')}
              </div>
              <div className="form-group">
                <label>Nombre institución</label>
                <input
                  value={form.institucionNombre}
                  onChange={e => actualizarCampo('institucionNombre', e.target.value)}
                  placeholder="Ej: Clínica Central"
                />
                {renderError('institucionNombre')}
              </div>
            </div>
          )}

          <div className="registro-grid">
            <div className="form-group">
              <label>Región *</label>
              <div className="select-field">
                <input
                  value={regionSearch}
                  onChange={(e) => {
                    setRegionSearch(e.target.value)
                    actualizarCampo('regionId', null)
                    actualizarCampo('regionNombre', '')
                  }}
                  onFocus={() => setRegionAbierto(true)}
                  onBlur={() => setTimeout(() => setRegionAbierto(false), 150)}
                  placeholder={cargandoRegiones ? 'Cargando regiones...' : 'Busca una región'}
                  aria-invalid={Boolean(errores.regionId)}
                />
                {regionAbierto && (
                  <div className="select-options">
                    {filtrarOpciones(regiones, regionSearch).map((region) => (
                      <button
                        type="button"
                        key={region.id}
                        onClick={() => seleccionarRegion(region)}
                      >
                        {region.nombre}
                      </button>
                    ))}
                    {!filtrarOpciones(regiones, regionSearch).length && (
                      <span className="select-empty">Sin resultados</span>
                    )}
                  </div>
                )}
              </div>
              {renderError('regionId')}
            </div>
            <div className="form-group">
              <label>Comuna *</label>
              <div className="select-field">
                <input
                  value={comunaSearch}
                  onChange={(e) => {
                    setComunaSearch(e.target.value)
                    actualizarCampo('comunaId', null)
                    actualizarCampo('comunaNombre', '')
                  }}
                  onFocus={() => {
                    if (form.regionId) setComunaAbierto(true)
                  }}
                  onBlur={() => setTimeout(() => setComunaAbierto(false), 150)}
                  placeholder={form.regionId ? (cargandoComunas ? 'Cargando comunas...' : 'Busca una comuna') : 'Selecciona una región primero'}
                  disabled={!form.regionId || cargandoComunas}
                  aria-invalid={Boolean(errores.comunaId)}
                />
                {comunaAbierto && (
                  <div className="select-options">
                    {filtrarOpciones(comunas, comunaSearch).map((comuna) => (
                      <button
                        type="button"
                        key={comuna.id}
                        onClick={() => seleccionarComuna(comuna)}
                      >
                        {comuna.nombre}
                      </button>
                    ))}
                    {!filtrarOpciones(comunas, comunaSearch).length && (
                      <span className="select-empty">Sin resultados</span>
                    )}
                  </div>
                )}
              </div>
              {renderError('comunaId')}
            </div>
          </div>

          <div className="registro-grid">
            <div className="form-group registro-full">
              <label>Dirección *</label>
              <input
                value={form.direccion}
                onChange={e => actualizarCampo('direccion', e.target.value)}
                placeholder="Ej: Calle 123"
              />
              {renderError('direccion')}
            </div>
            <div className="form-group">
              <label>Número *</label>
              <input
                value={form.numDireccion}
                onChange={e => actualizarCampo('numDireccion', e.target.value)}
                placeholder="Ej: 45"
              />
              {renderError('numDireccion')}
            </div>
            <div className="form-group">
              <label>Detalle</label>
              <input
                value={form.detalleDireccion}
                onChange={e => actualizarCampo('detalleDireccion', e.target.value)}
                placeholder="Ej: Depto 201"
              />
            </div>
            <div className="form-group">
              <label>Referencia</label>
              <input
                value={form.referencia}
                onChange={e => actualizarCampo('referencia', e.target.value)}
                placeholder="Ej: Cerca de la plaza"
              />
            </div>
            <div className="form-group">
              <label>Nombre receptor</label>
              <input
                value={form.nombreReceptor}
                onChange={e => actualizarCampo('nombreReceptor', e.target.value)}
                placeholder="Ej: Juan Pérez"
              />
            </div>
            <div className="form-group">
              <label>Teléfono receptor</label>
              <input
                value={form.telefonoReceptor}
                onChange={e => actualizarCampo('telefonoReceptor', e.target.value)}
                placeholder="Ej: +56998765432"
              />
            </div>
          </div>

          <div className="registro-grid">
            <div className="form-group">
              <label>Contraseña *</label>
              <div className="password-field">
                <input
                  type={mostrarPassword ? 'text' : 'password'}
                  value={form.password}
                  onChange={e => actualizarCampo('password', e.target.value)}
                />
                <button
                  type="button"
                  className="password-toggle"
                  onClick={() => setMostrarPassword(prev => !prev)}
                  aria-label={mostrarPassword ? 'Ocultar contraseña' : 'Mostrar contraseña'}
                >
                  {mostrarPassword ? (
                    <svg className="password-toggle-icon" viewBox="0 0 24 24" aria-hidden="true">
                      <path
                        fill="currentColor"
                        d="M12 5c5.05 0 9.27 3.11 11 7.5-1.05 2.62-3.02 4.78-5.5 6.06l1.56 1.56-1.42 1.42L2.1 5.4 3.5 4l3.02 3.02C8.2 5.75 10.03 5 12 5zm0 3a4 4 0 0 0-2.9 1.25l1.53 1.53A2 2 0 0 1 14 12a2 2 0 0 1-.78 1.58l1.5 1.5A4 4 0 0 0 12 8zm-6.93-.93 2 2C5.44 10.14 4.05 11.68 3 13.5 4.73 17.89 8.95 21 14 21c1.1 0 2.16-.14 3.16-.4l-2.02-2.02A7.77 7.77 0 0 1 14 19c-3.53 0-6.66-2-8.08-5 1.02-2.2 2.78-4.02 4.85-4.93z"
                      />
                    </svg>
                  ) : (
                    <svg className="password-toggle-icon" viewBox="0 0 24 24" aria-hidden="true">
                      <path
                        fill="currentColor"
                        d="M12 5c5.05 0 9.27 3.11 11 7.5C21.27 16.89 17.05 20 12 20S2.73 16.89 1 12.5C2.73 8.11 6.95 5 12 5zm0 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8zm0 2a2 2 0 1 1 0 4 2 2 0 0 1 0-4z"
                      />
                    </svg>
                  )}
                </button>
              </div>
              {renderError('password')}
            </div>
            <div className="form-group">
              <label>Confirmar contraseña *</label>
              <div className="password-field">
                <input
                  type={mostrarConfirmacion ? 'text' : 'password'}
                  value={form.confirmPassword}
                  onChange={e => actualizarCampo('confirmPassword', e.target.value)}
                />
                <button
                  type="button"
                  className="password-toggle"
                  onClick={() => setMostrarConfirmacion(prev => !prev)}
                  aria-label={mostrarConfirmacion ? 'Ocultar confirmación' : 'Mostrar confirmación'}
                >
                  {mostrarConfirmacion ? (
                    <svg className="password-toggle-icon" viewBox="0 0 24 24" aria-hidden="true">
                      <path
                        fill="currentColor"
                        d="M12 5c5.05 0 9.27 3.11 11 7.5-1.05 2.62-3.02 4.78-5.5 6.06l1.56 1.56-1.42 1.42L2.1 5.4 3.5 4l3.02 3.02C8.2 5.75 10.03 5 12 5zm0 3a4 4 0 0 0-2.9 1.25l1.53 1.53A2 2 0 0 1 14 12a2 2 0 0 1-.78 1.58l1.5 1.5A4 4 0 0 0 12 8zm-6.93-.93 2 2C5.44 10.14 4.05 11.68 3 13.5 4.73 17.89 8.95 21 14 21c1.1 0 2.16-.14 3.16-.4l-2.02-2.02A7.77 7.77 0 0 1 14 19c-3.53 0-6.66-2-8.08-5 1.02-2.2 2.78-4.02 4.85-4.93z"
                      />
                    </svg>
                  ) : (
                    <svg className="password-toggle-icon" viewBox="0 0 24 24" aria-hidden="true">
                      <path
                        fill="currentColor"
                        d="M12 5c5.05 0 9.27 3.11 11 7.5C21.27 16.89 17.05 20 12 20S2.73 16.89 1 12.5C2.73 8.11 6.95 5 12 5zm0 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8zm0 2a2 2 0 1 1 0 4 2 2 0 0 1 0-4z"
                      />
                    </svg>
                  )}
                </button>
              </div>
              {renderError('confirmPassword')}
            </div>
          </div>

          <button type="submit" className="btn btn-primary btn-block btn-lg" disabled={enviando}>
            {enviando ? 'Creando cuenta...' : 'Crear cuenta'}
          </button>
        </form>

        <p className="registro-login-link">
          ¿Ya tienes cuenta? <Link to="/login">Inicia sesión</Link>
        </p>
      </section>
    </main>
  )
}

import { useState, useEffect } from 'react'
import { Link } from 'react-router-dom'
import { registrarUsuario, obtenerRegiones, obtenerComunas } from '../services/api'
import './RegistroPage.css'

const TIPO_CLIENTE = {
  particular: 'PARTICULAR',
  institucional: 'INSTITUCIONAL',
}

const FORM_INICIAL = {
  tipoCliente: TIPO_CLIENTE.particular,
  nombre: '',
  apellido: '',
  email: '',
  telefono: '',
  rut: '',
  pasaporte: '',
  institucionId: '',
  institucionNombre: '',
  regionId: null,
  regionNombre: '',
  comunaId: null,
  comunaNombre: '',
  direccion: '',
  numDireccion: '',
  detalleDireccion: '',
  referencia: '',
  nombreReceptor: '',
  telefonoReceptor: '',
  password: '',
  confirmPassword: '',
}

function normalizarBusqueda(valor) {
  return String(valor || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
}

function escapeRegExp(valor) {
  return String(valor || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
}

function filtrarOpciones(opciones, busqueda) {
  const query = normalizarBusqueda(busqueda)
  if (!query) return opciones
  const regex = new RegExp(escapeRegExp(query))
  return opciones.filter((opcion) => regex.test(normalizarBusqueda(opcion.nombre)))
}

function validarEmail(email) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)
}

function validarTextoGeneral(valor) {
  const texto = String(valor || '').trim()
  if (texto.length < 2) return false
  return !/^\d+$/.test(texto)
}

function validarTelefonoChileno(valor) {
  const telefono = String(valor || '').trim()
  if (!/^\+?\d+$/.test(telefono)) return false

  if (telefono.startsWith('+56')) {
    const numero = telefono.slice(3)
    return /^\d{8,9}$/.test(numero)
  }

  return /^\d{8,9}$/.test(telefono)
}

function limpiarRut(rut) {
  return String(rut || '').replace(/\./g, '').replace(/-/g, '').trim().toUpperCase()
}

function calcularDigitoRut(cuerpo) {
  let suma = 0
  let multiplo = 2

  for (let i = cuerpo.length - 1; i >= 0; i -= 1) {
    suma += Number(cuerpo[i]) * multiplo
    multiplo = multiplo === 7 ? 2 : multiplo + 1
  }

  const resto = 11 - (suma % 11)
  if (resto === 11) return '0'
  if (resto === 10) return 'K'
  return String(resto)
}

function validarRutChileno(rut) {
  const limpio = limpiarRut(rut)
  if (!/^\d{6,8}[0-9K]$/.test(limpio)) return false

  const cuerpo = limpio.slice(0, -1)
  const dv = limpio.slice(-1)
  return calcularDigitoRut(cuerpo) === dv
}

export default function RegistroPage() {
  const [form, setForm] = useState(FORM_INICIAL)
  const [errores, setErrores] = useState({})
  const [enviado, setEnviado] = useState(false)
  const [enviando, setEnviando] = useState(false)
  const [mostrarPassword, setMostrarPassword] = useState(false)
  const [mostrarConfirmacion, setMostrarConfirmacion] = useState(false)
  const [regiones, setRegiones] = useState([])
  const [comunas, setComunas] = useState([])
  const [cargandoRegiones, setCargandoRegiones] = useState(false)
  const [cargandoComunas, setCargandoComunas] = useState(false)
  const [regionSearch, setRegionSearch] = useState('')
  const [comunaSearch, setComunaSearch] = useState('')
  const [regionAbierto, setRegionAbierto] = useState(false)
  const [comunaAbierto, setComunaAbierto] = useState(false)

  const esInstitucional = form.tipoCliente === TIPO_CLIENTE.institucional

  useEffect(() => {
    const cargarRegiones = async () => {
      try {
        setCargandoRegiones(true)
        const { data } = await obtenerRegiones()
        setRegiones(data || [])
      } finally {
        setCargandoRegiones(false)
      }
    }

    cargarRegiones()
  }, [])

  useEffect(() => {
    if (!form.regionId) {
      setComunas([])
      setComunaSearch('')
      return
    }

    const cargarComunas = async () => {
      try {
        setCargandoComunas(true)
        const { data } = await obtenerComunas({ region_id: form.regionId })
        setComunas(data || [])
      } finally {
        setCargandoComunas(false)
      }
    }

    cargarComunas()
  }, [form.regionId])

  const actualizarCampo = (campo, valor) => {
    setForm(prev => ({ ...prev, [campo]: valor }))
    setErrores(prev => {
      if (campo === 'tipoCliente') return {}
      return { ...prev, [campo]: '' }
    })
    setEnviado(false)
  }

  const seleccionarRegion = (region) => {
    actualizarCampo('regionId', region.id)
    actualizarCampo('regionNombre', region.nombre)
    actualizarCampo('comunaId', null)
    actualizarCampo('comunaNombre', '')
    setRegionSearch(region.nombre)
    setComunaSearch('')
    setRegionAbierto(false)
  }

  const seleccionarComuna = (comuna) => {
    actualizarCampo('comunaId', comuna.id)
    actualizarCampo('comunaNombre', comuna.nombre)
    setComunaSearch(comuna.nombre)
    setComunaAbierto(false)
  }

  const validarFormulario = () => {
    const nuevosErrores = {}
    const requeridos = [
      'nombre',
      'apellido',
      'email',
      'telefono',
      'direccion',
      'numDireccion',
      'password',
      'confirmPassword',
    ]

    requeridos.forEach(campo => {
      if (!String(form[campo] || '').trim()) {
        nuevosErrores[campo] = 'Este campo es obligatorio.'
      }
    })

    if (!form.regionId) nuevosErrores.regionId = 'Selecciona una región.'
    if (!form.comunaId) nuevosErrores.comunaId = 'Selecciona una comuna.'

    if (!form.rut && !form.pasaporte) {
      nuevosErrores.rut = 'Debes ingresar RUT o pasaporte.'
      nuevosErrores.pasaporte = 'Debes ingresar RUT o pasaporte.'
    }

    if (form.rut && form.pasaporte) {
      nuevosErrores.rut = 'No puedes ingresar RUT y pasaporte a la vez.'
      nuevosErrores.pasaporte = 'No puedes ingresar RUT y pasaporte a la vez.'
    }

    if (form.rut && !validarRutChileno(form.rut)) {
      nuevosErrores.rut = 'Ingresa un RUT válido.'
    }

    if (esInstitucional && !form.rut) {
      nuevosErrores.rut = 'Para institucional, el RUT es obligatorio.'
    }

    if (esInstitucional && form.institucionId && form.institucionNombre) {
      nuevosErrores.institucionId = 'Usa ID o nombre, pero no ambos.'
      nuevosErrores.institucionNombre = 'Usa ID o nombre, pero no ambos.'
    }

    if (esInstitucional && !form.institucionId && !form.institucionNombre) {
      nuevosErrores.institucionId = 'Ingresa una institución o su ID.'
      nuevosErrores.institucionNombre = 'Ingresa una institución o su ID.'
    }

    const textosGenerales = ['nombre', 'apellido']
    textosGenerales.forEach(campo => {
      if (form[campo] && !validarTextoGeneral(form[campo])) {
        nuevosErrores[campo] = 'Debe tener al menos 2 caracteres y no puede ser solo números.'
      }
    })

    if (form.email && !validarEmail(form.email)) {
      nuevosErrores.email = 'Ingresa un correo electrónico válido.'
    }

    if (form.telefono && !validarTelefonoChileno(form.telefono)) {
      nuevosErrores.telefono = 'Ingresa un teléfono válido.'
    }

    if (form.password && form.password.length < 6) {
      nuevosErrores.password = 'La contraseña debe tener al menos 6 caracteres.'
    }

    if (form.password && form.confirmPassword && form.password !== form.confirmPassword) {
      nuevosErrores.confirmPassword = 'Las contraseñas no coinciden.'
    }

    setErrores(nuevosErrores)
    return Object.keys(nuevosErrores).length === 0
  }

  const handleSubmit = async (event) => {
    event.preventDefault()
    setEnviado(false)

    if (!validarFormulario()) return

    const usuario = {
      username: form.email,
      email: form.email,
      first_name: form.nombre,
      last_name: form.apellido,
      password: form.password,
      password2: form.confirmPassword,
    }

    const direccionEntrega = {
      direccion: form.direccion,
      num_direccion: form.numDireccion,
      detalle_direccion: form.detalleDireccion || null,
      comuna: form.comunaId,
      referencia: form.referencia || null,
      nombre_receptor: form.nombreReceptor || null,
      telefono_receptor: form.telefonoReceptor || null,
      es_principal: true,
    }

    const payload = {
      usuario,
      rut: form.rut || null,
      pasaporte: form.pasaporte || null,
      tipo_cliente: form.tipoCliente,
      telefono: form.telefono,
      institucion_id: null,
      datos_institucion: null,
      direccion_entrega: direccionEntrega,
    }

    if (esInstitucional) {
      if (form.institucionId) {
        payload.institucion_id = Number(form.institucionId)
      } else {
        payload.datos_institucion = { nombre: form.institucionNombre }
      }
    }

    try {
      setEnviando(true)
      await registrarUsuario(payload)
      setEnviado(true)
      setForm(FORM_INICIAL)
      setRegionSearch('')
      setComunaSearch('')
    } catch (error) {
      const data = error.response?.data
      setErrores(
        data && typeof data === 'object'
          ? data
          : { general: 'No se pudo crear la cuenta. Intenta nuevamente.' }
      )
    } finally {
      setEnviando(false)
    }
  }

  const renderError = (campo) =>
    errores[campo] ? <span className="registro-error">{errores[campo]}</span> : null

  return (
    <main className="registro-page">
      <section className="registro-card">
        <div className="registro-header">
          <span className="registro-kicker">Nueva cuenta</span>
          <h1>Crear cuenta MEDISTOCK</h1>
          <p>Regístrate como paciente o cliente institucional.</p>
        </div>

        {enviado && (
          <div className="alert alert-success">
            Cuenta creada correctamente. Ya puedes iniciar sesión.
          </div>
        )}

        {errores.general && (
          <div className="alert alert-danger">
            {errores.general}
          </div>
        )}

        <form onSubmit={handleSubmit} noValidate>
          <fieldset className="registro-tipo">
            <legend>Tipo de cliente</legend>
            <button
              type="button"
              className={`tipo-card ${!esInstitucional ? 'tipo-card-activo' : ''}`}
              onClick={() => actualizarCampo('tipoCliente', TIPO_CLIENTE.particular)}
            >
              <strong>Particular</strong>
              <span>Compra para uso personal.</span>
            </button>
            <button
              type="button"
              className={`tipo-card ${esInstitucional ? 'tipo-card-activo' : ''}`}
              onClick={() => actualizarCampo('tipoCliente', TIPO_CLIENTE.institucional)}
            >
              <strong>Institucional</strong>
              <span>Cuenta para instituciones o empresas.</span>
            </button>
          </fieldset>

          <div className="registro-grid">
            <div className="form-group">
              <label>Nombre *</label>
              <input
                value={form.nombre}
                onChange={e => actualizarCampo('nombre', e.target.value)}
                placeholder="Ej: Carla"
              />
              {renderError('nombre')}
            </div>
            <div className="form-group">
              <label>Apellido *</label>
              <input
                value={form.apellido}
                onChange={e => actualizarCampo('apellido', e.target.value)}
                placeholder="Ej: González"
              />
              {renderError('apellido')}
            </div>
            <div className="form-group">
              <label>Correo electrónico *</label>
              <input
                type="email"
                value={form.email}
                onChange={e => actualizarCampo('email', e.target.value)}
                placeholder="correo@dominio.com"
              />
              {renderError('email')}
            </div>
            <div className="form-group">
              <label>Teléfono *</label>
              <input
                value={form.telefono}
                onChange={e => actualizarCampo('telefono', e.target.value)}
                placeholder="+56912345678"
              />
              {renderError('telefono')}
            </div>
            <div className="form-group">
              <label>RUT</label>
              <input
                value={form.rut}
                onChange={e => actualizarCampo('rut', e.target.value)}
                placeholder="12.345.678-5"
              />
              {renderError('rut')}
            </div>
            <div className="form-group">
              <label>Pasaporte</label>
              <input
                value={form.pasaporte}
                onChange={e => actualizarCampo('pasaporte', e.target.value)}
                placeholder="Ej: AB123456"
              />
              {renderError('pasaporte')}
            </div>
          </div>

          {esInstitucional && (
            <div className="registro-grid">
              <div className="form-group">
                <label>ID institución</label>
                <input
                  value={form.institucionId}
                  onChange={e => actualizarCampo('institucionId', e.target.value)}
                  placeholder="Ej: 12"
                />
                {renderError('institucionId')}
              </div>
              <div className="form-group">
                <label>Nombre institución</label>
                <input
                  value={form.institucionNombre}
                  onChange={e => actualizarCampo('institucionNombre', e.target.value)}
                  placeholder="Ej: Clínica Central"
                />
                {renderError('institucionNombre')}
              </div>
            </div>
          )}

          <div className="registro-grid">
            <div className="form-group">
              <label>Región *</label>
              <div className="select-field">
                <input
                  value={regionSearch}
                  onChange={(e) => {
                    setRegionSearch(e.target.value)
                    actualizarCampo('regionId', null)
                    actualizarCampo('regionNombre', '')
                  }}
                  onFocus={() => setRegionAbierto(true)}
                  onBlur={() => setTimeout(() => setRegionAbierto(false), 150)}
                  placeholder={cargandoRegiones ? 'Cargando regiones...' : 'Busca una región'}
                  aria-invalid={Boolean(errores.regionId)}
                />
                {regionAbierto && (
                  <div className="select-options">
                    {filtrarOpciones(regiones, regionSearch).map((region) => (
                      <button
                        type="button"
                        key={region.id}
                        onClick={() => seleccionarRegion(region)}
                      >
                        {region.nombre}
                      </button>
                    ))}
                    {!filtrarOpciones(regiones, regionSearch).length && (
                      <span className="select-empty">Sin resultados</span>
                    )}
                  </div>
                )}
              </div>
              {renderError('regionId')}
            </div>
            <div className="form-group">
              <label>Comuna *</label>
              <div className="select-field">
                <input
                  value={comunaSearch}
                  onChange={(e) => {
                    setComunaSearch(e.target.value)
                    actualizarCampo('comunaId', null)
                    actualizarCampo('comunaNombre', '')
                  }}
                  onFocus={() => {
                    if (form.regionId) setComunaAbierto(true)
                  }}
                  onBlur={() => setTimeout(() => setComunaAbierto(false), 150)}
                  placeholder={form.regionId ? (cargandoComunas ? 'Cargando comunas...' : 'Busca una comuna') : 'Selecciona una región primero'}
                  disabled={!form.regionId || cargandoComunas}
                  aria-invalid={Boolean(errores.comunaId)}
                />
                {comunaAbierto && (
                  <div className="select-options">
                    {filtrarOpciones(comunas, comunaSearch).map((comuna) => (
                      <button
                        type="button"
                        key={comuna.id}
                        onClick={() => seleccionarComuna(comuna)}
                      >
                        {comuna.nombre}
                      </button>
                    ))}
                    {!filtrarOpciones(comunas, comunaSearch).length && (
                      <span className="select-empty">Sin resultados</span>
                    )}
                  </div>
                )}
              </div>
              {renderError('comunaId')}
            </div>
          </div>

          <div className="registro-grid">
            <div className="form-group registro-full">
              <label>Dirección *</label>
              <input
                value={form.direccion}
                onChange={e => actualizarCampo('direccion', e.target.value)}
                placeholder="Ej: Calle 123"
              />
              {renderError('direccion')}
            </div>
            <div className="form-group">
              <label>Número *</label>
              <input
                value={form.numDireccion}
                onChange={e => actualizarCampo('numDireccion', e.target.value)}
                placeholder="Ej: 45"
              />
              {renderError('numDireccion')}
            </div>
            <div className="form-group">
              <label>Detalle</label>
              <input
                value={form.detalleDireccion}
                onChange={e => actualizarCampo('detalleDireccion', e.target.value)}
                placeholder="Ej: Depto 201"
              />
            </div>
            <div className="form-group">
              <label>Referencia</label>
              <input
                value={form.referencia}
                onChange={e => actualizarCampo('referencia', e.target.value)}
                placeholder="Ej: Cerca de la plaza"
              />
            </div>
            <div className="form-group">
              <label>Nombre receptor</label>
              <input
                value={form.nombreReceptor}
                onChange={e => actualizarCampo('nombreReceptor', e.target.value)}
                placeholder="Ej: Juan Pérez"
              />
            </div>
            <div className="form-group">
              <label>Teléfono receptor</label>
              <input
                value={form.telefonoReceptor}
                onChange={e => actualizarCampo('telefonoReceptor', e.target.value)}
                placeholder="Ej: +56998765432"
              />
            </div>
          </div>

          <div className="registro-grid">
            <div className="form-group">
              <label>Contraseña *</label>
              <div className="password-field">
                <input
                  type={mostrarPassword ? 'text' : 'password'}
                  value={form.password}
                  onChange={e => actualizarCampo('password', e.target.value)}
                />
                <button
                  type="button"
                  className="password-toggle"
                  onClick={() => setMostrarPassword(prev => !prev)}
                  aria-label={mostrarPassword ? 'Ocultar contraseña' : 'Mostrar contraseña'}
                >
                  {mostrarPassword ? (
                    <svg className="password-toggle-icon" viewBox="0 0 24 24" aria-hidden="true">
                      <path
                        fill="currentColor"
                        d="M12 5c5.05 0 9.27 3.11 11 7.5-1.05 2.62-3.02 4.78-5.5 6.06l1.56 1.56-1.42 1.42L2.1 5.4 3.5 4l3.02 3.02C8.2 5.75 10.03 5 12 5zm0 3a4 4 0 0 0-2.9 1.25l1.53 1.53A2 2 0 0 1 14 12a2 2 0 0 1-.78 1.58l1.5 1.5A4 4 0 0 0 12 8zm-6.93-.93 2 2C5.44 10.14 4.05 11.68 3 13.5 4.73 17.89 8.95 21 14 21c1.1 0 2.16-.14 3.16-.4l-2.02-2.02A7.77 7.77 0 0 1 14 19c-3.53 0-6.66-2-8.08-5 1.02-2.2 2.78-4.02 4.85-4.93z"
                      />
                    </svg>
                  ) : (
                    <svg className="password-toggle-icon" viewBox="0 0 24 24" aria-hidden="true">
                      <path
                        fill="currentColor"
                        d="M12 5c5.05 0 9.27 3.11 11 7.5C21.27 16.89 17.05 20 12 20S2.73 16.89 1 12.5C2.73 8.11 6.95 5 12 5zm0 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8zm0 2a2 2 0 1 1 0 4 2 2 0 0 1 0-4z"
                      />
                    </svg>
                  )}
                </button>
              </div>
              {renderError('password')}
            </div>
            <div className="form-group">
              <label>Confirmar contraseña *</label>
              <div className="password-field">
                <input
                  type={mostrarConfirmacion ? 'text' : 'password'}
                  value={form.confirmPassword}
                  onChange={e => actualizarCampo('confirmPassword', e.target.value)}
                />
                <button
                  type="button"
                  className="password-toggle"
                  onClick={() => setMostrarConfirmacion(prev => !prev)}
                  aria-label={mostrarConfirmacion ? 'Ocultar confirmación' : 'Mostrar confirmación'}
                >
                  {mostrarConfirmacion ? (
                    <svg className="password-toggle-icon" viewBox="0 0 24 24" aria-hidden="true">
                      <path
                        fill="currentColor"
                        d="M12 5c5.05 0 9.27 3.11 11 7.5-1.05 2.62-3.02 4.78-5.5 6.06l1.56 1.56-1.42 1.42L2.1 5.4 3.5 4l3.02 3.02C8.2 5.75 10.03 5 12 5zm0 3a4 4 0 0 0-2.9 1.25l1.53 1.53A2 2 0 0 1 14 12a2 2 0 0 1-.78 1.58l1.5 1.5A4 4 0 0 0 12 8zm-6.93-.93 2 2C5.44 10.14 4.05 11.68 3 13.5 4.73 17.89 8.95 21 14 21c1.1 0 2.16-.14 3.16-.4l-2.02-2.02A7.77 7.77 0 0 1 14 19c-3.53 0-6.66-2-8.08-5 1.02-2.2 2.78-4.02 4.85-4.93z"
                      />
                    </svg>
                  ) : (
                    <svg className="password-toggle-icon" viewBox="0 0 24 24" aria-hidden="true">
                      <path
                        fill="currentColor"
                        d="M12 5c5.05 0 9.27 3.11 11 7.5C21.27 16.89 17.05 20 12 20S2.73 16.89 1 12.5C2.73 8.11 6.95 5 12 5zm0 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8zm0 2a2 2 0 1 1 0 4 2 2 0 0 1 0-4z"
                      />
                    </svg>
                  )}
                </button>
              </div>
              {renderError('confirmPassword')}
            </div>
          </div>

          <button type="submit" className="btn btn-primary btn-block btn-lg" disabled={enviando}>
            {enviando ? 'Creando cuenta...' : 'Crear cuenta'}
          </button>
        </form>

        <p className="registro-login-link">
          ¿Ya tienes cuenta? <Link to="/login">Inicia sesión</Link>
        </p>
      </section>
    </main>
  )
}
